package dev.demperor.bitwig.a49;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Minimal bitmap font loaded from the JSON glyph strip in
 * {@code src/main/resources/icons/charmap_font.json}.
 *
 * <p>The resource format is generated by the separate charmap tool and is
 * deliberately simpler than a full JSON parser. Widths are stored per glyph;
 * a fixed one-pixel letter spacing is applied when drawing and measuring.</p>
 */
public final class A49BitmapFont
{
    private static final Pattern LABEL_PATTERN = Pattern.compile("\\\"label\\\"\\s*:\\s*\\\"((?:\\\\.|[^\\\"])*)\\\"");
    private static final Pattern WIDTH_PATTERN = Pattern.compile("\\\"width\\\"\\s*:\\s*(\\d+)");
    private static final Pattern HEIGHT_PATTERN = Pattern.compile("\\\"height\\\"\\s*:\\s*(\\d+)");
    private static final Pattern PIXELS_PATTERN = Pattern.compile("\\\"pixels\\\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);

    private final Map<Character, Glyph> glyphsByChar;
    private final int lineHeight;
    private final int letterSpacing;
    private final int wordSpacing;

    private A49BitmapFont(final Map<Character, Glyph> glyphsByChar, final int lineHeight, final int letterSpacing)
    {
        this.glyphsByChar = glyphsByChar;
        this.lineHeight = Math.max(1, lineHeight);
        this.letterSpacing = Math.max(0, letterSpacing);
        this.wordSpacing = this.letterSpacing + 1;
    }

    public static A49BitmapFont loadFromResource(final String resourcePath) throws IOException
    {
        final InputStream in = A49BitmapFont.class.getResourceAsStream(resourcePath);
        if (in == null)
            throw new IOException("Resource not found: " + resourcePath);

        final StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
        {
            String line;
            while ((line = reader.readLine()) != null)
                sb.append(line);
        }

        final String json = sb.toString();
        final int glyphsKey = indexOfJsonKey(json, "glyphs", 0);
        if (glyphsKey < 0)
            throw new IOException("No glyphs array found in font resource: " + resourcePath);

        final int glyphsArrayStart = json.indexOf('[', glyphsKey);
        if (glyphsArrayStart < 0)
            throw new IOException("Malformed glyphs array in font resource: " + resourcePath);
        final int glyphsArrayEnd = findArrayEnd(json, glyphsArrayStart + 1);
        final String glyphsJson = json.substring(glyphsArrayStart + 1, glyphsArrayEnd);

        final Map<Character, Glyph> glyphs = new HashMap<Character, Glyph>();
        int maxHeight = 0;
        int index = 0;
        while (true)
        {
            final int objectStart = glyphsJson.indexOf('{', index);
            if (objectStart < 0)
                break;
            final int objectEnd = findObjectEnd(glyphsJson, objectStart + 1);
            final String objectJson = glyphsJson.substring(objectStart, objectEnd + 1);

            final String labelText = matchGroup(LABEL_PATTERN, objectJson, 1, "label");
            final int width = Integer.parseInt(matchGroup(WIDTH_PATTERN, objectJson, 1, "width"));
            final int height = Integer.parseInt(matchGroup(HEIGHT_PATTERN, objectJson, 1, "height"));
            final String pixelsBody = matchGroup(PIXELS_PATTERN, objectJson, 1, "pixels");

            final boolean[] pixels = parsePixels(pixelsBody, width * height);
            if (!labelText.isEmpty())
            {
                final char ch = unescapeJsonString(labelText).charAt(0);
                glyphs.put(Character.valueOf(ch), new Glyph(width, height, pixels));
            }
            maxHeight = Math.max(maxHeight, height);
            index = objectEnd + 1;
        }

        if (glyphs.isEmpty())
            throw new IOException("No glyphs found in font resource: " + resourcePath);

        return new A49BitmapFont(Collections.unmodifiableMap(glyphs), maxHeight, 1);
    }

    public int getLineHeight()
    {
        return this.lineHeight;
    }

    public int measureText(final String text)
    {
        if (text == null || text.isEmpty())
            return 0;

        int width = 0;
        for (int i = 0; i < text.length(); i++)
        {
            final char ch = text.charAt(i);
            if (ch == ' ')
            {
                width += this.spaceWidth() + this.wordSpacing;
                continue;
            }
            final Glyph glyph = this.lookupGlyph(ch);
            width += glyph == null ? this.spaceWidth() : glyph.width;
            if (i < text.length() - 1)
                width += this.letterSpacing;
        }
        return Math.max(0, width);
    }

    public void drawText(final Graphics2DProxy g, final int x, final int y, final String text)
    {
        if (text == null || text.isEmpty())
            return;

        int cursorX = x;
        for (int i = 0; i < text.length(); i++)
        {
            final char ch = text.charAt(i);
            if (ch == ' ')
            {
                cursorX += this.spaceWidth() + this.wordSpacing;
                continue;
            }
            final Glyph glyph = this.lookupGlyph(ch);
            if (glyph != null)
            {
                glyph.draw(g, cursorX, y);
                cursorX += glyph.width;
            }
            else
                cursorX += this.spaceWidth();
            if (i < text.length() - 1)
                cursorX += this.letterSpacing;
        }
    }

    public List<String> wrapText(final String text, final int maxWidth, final int maxLines)
    {
        if (text == null || text.trim().isEmpty())
            return Collections.singletonList("");

        final String normalized = text.replace('\u2014', ' ').replaceAll("\\s+", " ").trim();
        final String[] words = normalized.split(" ");
        final List<String> lines = new ArrayList<String>();
        String current = "";

        for (final String word : words)
        {
            final String candidate = current.isEmpty() ? word : current + ' ' + word;
            if (!current.isEmpty() && this.measureText(candidate) > maxWidth)
            {
                lines.add(current);
                current = word;
                if (lines.size() >= maxLines - 1)
                    break;
            }
            else
                current = candidate;
        }

        if (!current.isEmpty() && lines.size() < maxLines)
            lines.add(current);

        if (lines.isEmpty())
            lines.add(this.trimToWidth(normalized, maxWidth));
        else if (lines.size() == maxLines && this.measureText(lines.get(lines.size() - 1)) > maxWidth)
            lines.set(lines.size() - 1, this.trimToWidth(lines.get(lines.size() - 1), maxWidth));
        return lines;
    }

    private String trimToWidth(final String text, final int maxWidth)
    {
        if (text == null)
            return "";
        if (this.measureText(text) <= maxWidth)
            return text;

        final Glyph fallback = this.lookupGlyph('?');
        final int fallbackWidth = fallback == null ? 0 : fallback.width;
        final StringBuilder sb = new StringBuilder();
        for (int i = 0; i < text.length(); i++)
        {
            final String next = sb.toString() + text.charAt(i);
            if (this.measureText(next) + fallbackWidth > maxWidth)
                break;
            sb.append(text.charAt(i));
        }
        if (fallback != null)
            sb.append('?');
        return sb.toString();
    }

    private int spaceWidth()
    {
        final Glyph space = this.lookupGlyph(' ');
        return space == null ? 4 : Math.max(2, space.width);
    }

    private Glyph lookupGlyph(final char ch)
    {
        Glyph glyph = this.glyphsByChar.get(Character.valueOf(ch));
        if (glyph == null && Character.isLetter(ch))
            glyph = this.glyphsByChar.get(Character.valueOf(Character.isUpperCase(ch) ? Character.toLowerCase(ch) : Character.toUpperCase(ch)));
        if (glyph == null)
            glyph = this.glyphsByChar.get(Character.valueOf('?'));
        return glyph;
    }

    private static boolean[] parsePixels(final String pixelsBody, final int expectedLength)
    {
        final boolean[] pixels = new boolean[Math.max(0, expectedLength)];
        final String[] parts = pixelsBody.trim().isEmpty() ? new String[0] : pixelsBody.split(",");
        for (int i = 0; i < pixels.length && i < parts.length; i++)
            pixels[i] = Integer.parseInt(parts[i].trim()) == 0;
        return pixels;
    }

    private static String matchGroup(final Pattern pattern, final String text, final int group, final String fieldName) throws IOException
    {
        final Matcher matcher = pattern.matcher(text);
        if (!matcher.find())
            throw new IOException("Missing field '" + fieldName + "' in font glyph");
        return matcher.group(group);
    }

    private static int indexOfJsonKey(final String text, final String key, final int start)
    {
        return text.indexOf('"' + key + '"', start);
    }

    private static int findArrayEnd(final String text, final int contentStart) throws IOException
    {
        int depth = 1;
        boolean inString = false;
        boolean escape = false;
        for (int i = contentStart; i < text.length(); i++)
        {
            final char ch = text.charAt(i);
            if (escape)
            {
                escape = false;
                continue;
            }
            if (ch == '\\')
            {
                escape = true;
                continue;
            }
            if (ch == '"')
            {
                inString = !inString;
                continue;
            }
            if (inString)
                continue;
            if (ch == '[')
                depth++;
            else if (ch == ']')
            {
                depth--;
                if (depth == 0)
                    return i;
            }
        }
        throw new IOException("Unterminated JSON array.");
    }

    private static int findObjectEnd(final String text, final int contentStart) throws IOException
    {
        int depth = 1;
        boolean inString = false;
        boolean escape = false;
        for (int i = contentStart; i < text.length(); i++)
        {
            final char ch = text.charAt(i);
            if (escape)
            {
                escape = false;
                continue;
            }
            if (ch == '\\')
            {
                escape = true;
                continue;
            }
            if (ch == '"')
            {
                inString = !inString;
                continue;
            }
            if (inString)
                continue;
            if (ch == '{')
                depth++;
            else if (ch == '}')
            {
                depth--;
                if (depth == 0)
                    return i;
            }
        }
        throw new IOException("Unterminated JSON object.");
    }

    private static String unescapeJsonString(final String text)
    {
        return text.replace("\\\\", "\\").replace("\\\"", "\"");
    }

    public interface Graphics2DProxy
    {
        void fillRect(int x, int y, int width, int height);
    }

    private static final class Glyph
    {
        private final int width;
        private final int height;
        private final boolean[] pixels;

        private Glyph(final int width, final int height, final boolean[] pixels)
        {
            this.width = width;
            this.height = height;
            this.pixels = pixels;
        }

        private void draw(final Graphics2DProxy g, final int x, final int y)
        {
            for (int py = 0; py < this.height; py++)
            {
                for (int px = 0; px < this.width; px++)
                {
                    if (this.pixels[(py * this.width) + px])
                        g.fillRect(x + px, y + py, 1, 1);
                }
            }
        }
    }
}
